import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    graph = [[] for _ in range(N)]
    max_z = 0

    for _ in range(M):
        x, y, z = map(int, input().split())
        x -= 1
        y -= 1
        graph[x].append((y, z))
        graph[y].append((x, z))
        max_z = max(max_z, z)

    value = [-1] * N
    answer = [0] * N
    bits = max(1, max_z.bit_length())

    for start in range(N):
        if value[start] != -1:
            continue

        value[start] = 0
        component = []
        q = deque([start])

        while q:
            v = q.popleft()
            component.append(v)

            for to, z in graph[v]:
                expected = value[v] ^ z
                if value[to] == -1:
                    value[to] = expected
                    q.append(to)
                elif value[to] != expected:
                    print(-1)
                    return

        n = len(component)
        root_shift = 0

        for b in range(bits):
            ones = 0
            mask = 1 << b
            for v in component:
                if value[v] & mask:
                    ones += 1

            if ones > n - ones:
                root_shift |= mask

        for v in component:
            answer[v] = value[v] ^ root_shift

    print(*answer)

if __name__ == "__main__":
